              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label htmlFor="k-max">Max. Teilnehmer</Label>
                <Input
                  id="k-max"
                  type="number"
                  min="1"
                  value={kursForm.max_teilnehmer}
                  onChange={e => setKursForm(f => ({ ...f, max_teilnehmer: e.target.value }))}
